from research_helpers import *
M=ev('https://www.sec.gov/Archives/edgar/data/1754068/000119312525056725/d925335dex993.htm','Issuer confirms March18 2025 completed AlloVir/Kalaris reverse merger and public-company rename; current successor business not inferred from proposed transaction.')
T=ev('https://kalaristx.com/','Current issuer identifies TH103 antiVEGF candidate in Phase1b/2.')
L=ev('https://www.sec.gov/Archives/edgar/data/1754068/000119312526110659/klrs-20251231.htm','Current issuer annual report confirms licensed intellectual property supporting TH103 and University of California license. Theia is Kalaris former corporate name, not assumed unrelated product owner.')
A=ev('https://www.sec.gov/Archives/edgar/data/1754068/000156459021005652/alvr-10k_20201231.htm','Historical issuer annual report names Viralym-M and ALVR106/107/108/109; respiratory, HBV, HHV8 and SARSCoV2-directed cell therapies.')
P=ev('https://www.sec.gov/Archives/edgar/data/1754068/000119312523130419/d483376dars.pdf','Issuer explicitly equates posoleucel, Viralym-M and ALVR105.')
D=ev('https://www.sec.gov/Archives/edgar/data/1754068/000095017024031879/alvr-20231231.htm','Issuer confirms December2023 discontinuation of PhaseIII posoleucel trials; current program-wide disposition not assumed from individual trial stops.')
al=[p('TH103','Anti-VEGF candidate developed by successor Kalaris.',T,'development',roles=['developer','licensee'],evidence=[T,L,M]),p('Posoleucel','Historical multi-virus-specific allogeneic T-cell therapy.',P,aliases=['ALVR105','Viralym-M'],evidence=[P,A,D])]
for name,desc in [('ALVR106','Historical multi-virus-specific respiratory T-cell therapy.'),('ALVR107','Historical HBV-directed T-cell therapy.'),('ALVR108','Historical HHV8-directed T-cell therapy.'),('ALVR109','Historical SARSCoV2-directed T-cell therapy.')]:al.append(p(name,desc,A))
G=ev('https://ir.gyretx.com/news-releases/news-release-details/gyre-therapeutics-reports-second-quarter-2026-and-year-date','August2026 issuer names commercial ETUARY/Etorel/Contiva, hydronidone NDA accepted, CG001419/CG009301 clinical programs.')
C=ev('https://ir.gyretx.com/news-releases/news-release-details/gyre-therapeutics-completes-acquisition-cullgen-create-us-and','May4 2026 Cullgen acquisition completed; acquired candidates linked as owner rather than invented original development.')
S=ev('https://www.gyretx.com/science/','Current issuer identifies F351/hydronidone,F528,CG923308 and CG620953. CG920953 appears once in body inconsistency; not inferred separate candidate or confirmed alias.')
I=ev('https://www.gyretx.com/wp-content/uploads/2026/06/pipeline-6_26-1.jpg','June2026 official pipeline image visually reviewed; CG620953/CG923308/F528 IND-enabling; F351 separate geography/indication stages are one molecule.')
F=ev('https://www.sec.gov/Archives/edgar/data/1124105/000119312526106251/gyre-20251231.htm','2025 annual report confirms clinical F573 and F230. Recent report identifies F230 endothelin-A antagonist, superseding old release agonist wording.')
H=ev('https://www.sec.gov/Archives/edgar/data/1124105/000119312521066564/d134078dex991.htm','Historical Catalyst issuer pipeline identifies MarzAA,DalcA,CB2679dGT,CB2782PEG,CB4332.')
X=ev('https://www.sec.gov/Archives/edgar/data/1124105/000114036123009748/brhc10049211_8k.htm','Catalyst sold MarzAA,DalcA and CB2679dGT to GC Biopharma February27 2023; recorded as historical developer, not current owner.')
V=ev('https://www.sec.gov/Archives/edgar/data/1124105/000156459022037555/cbio-10q_20220930.htm','Catalyst complement portfolio including CB2782PEG sold to Vertex May2022; historical developer link not current ownership.')
gy=[]
for name,desc,ingredient in [('ETUARY','Pirfenidone capsule product for pulmonary fibrosis.','pirfenidone'),('Etorel','Nintedanib ethanesulfonate soft-capsule product.','nintedanib ethanesulfonate'),('Contiva','Avatrombopag maleate tablet product.','avatrombopag maleate')]:gy.append(p(name,desc,G,'commercial',roles=['owner'],typ='product',attributes={'active_ingredient':ingredient,'ownership_scope':'controlled Gyre Pharmaceuticals subsidiary'}))
gy.append(p('Hydronidone','Antifibrotic candidate with distinct China CHB-fibrosis and US MASH programs.',S,'development',roles=['owner'],aliases=['F351'],evidence=[G,S,I],contexts=[{'application_key':'chb_liver_fibrosis','application_name':'CHB-associated liver fibrosis','geography_key':'China','development_stage':'registration','regulatory_status':'NDA accepted; not assumed marketing approval'},{'application_key':'mash_liver_fibrosis','application_name':'MASH-associated liver fibrosis','geography_key':'USA','development_stage':'clinical','regulatory_status':'investigational'}]))
for name,desc,life,src in [('F528','Non-antibacterial macrolide candidate for COPD.','research',S),('F573','Clinical candidate for liver injury and liver failure.','development',F),('F230','Clinical endothelin-receptor candidate for PAH.','development',F),('CG001419','TRK degrader candidate for cancer and pain.','development',G),('CG009301','GSPT1 degrader candidate for hematologic malignancy.','development',G),('CG620953','TYK2/JAK1 dual-degrader candidate.','research',S),('CG923308','CDK2/cyclinE dual-degrader candidate.','research',S)]:gy.append(p(name,desc,src,life,roles=['owner'],evidence=[src,C] if name.startswith('CG') else [src,I] if name=='F528' else [src]))
for name,desc,aliases in [('Marzeptacog alfa','Historical engineered factorVIIa candidate.',['MarzAA']),('Dalcinonacog alfa','Historical engineered factorIX candidate.',['DalcA']),('CB 2679d-GT','Historical factorIX gene-therapy candidate.',[])]:gy.append(p(name,desc,H,aliases=aliases,evidence=[H,X],attributes={'current_rights_note':'sold to GC Biopharma2023-02-27; original developer relationship only'}))
for name,desc in [('CB 2782-PEG','Historical complement-C3-degrading protease candidate.'),('CB 4332','Historical enhanced complement-factorI candidate.')]:gy.append(p(name,desc,H,evidence=[H,V],attributes={'current_rights_note':'legacy complement portfolio sold to Vertex May2022; detailed disposition of individual asset not assumed'}))
companies=[company('Allovir\u00a0Inc',al,[M,T,L,A,P,D],'Six named assets across legacy AlloVir and completed Kalaris successor business reviewed. Follow-up legacy rights disposition, program-wide status after posoleucel trial stops, and unnamed platform technology. No invented product from generic VST mechanism.'),company('Catalyst Biosciences Inc',gy,[G,C,S,I,F,H,X,V],'Sixteen named commercial/clinical/research assets across current Gyre and historical Catalyst reviewed. Cullgen ownership closing confirmed. Remaining follow-up branded degrader platforms, additional research codes, earlier Targacept predecessor catalogue, legacy coagulation aliases and current post-sale statuses. Source CG620953/CG920953 inconsistency retained as uncertainty rather than duplicate.')]
(out/'batch-0032.json').write_text(json.dumps({'companies':companies},indent=2));print(len(al),len(gy))
